THOUGHT: Let me create a simple test to see if there's an issue with reusing batches. Based on the changelog mentioning a fix for updating the committed flag, I suspect the issue might have been that the committed flag wasn't being set correctly in all cases.

Let me create a simple test script to check the current behavior:

```bash
cat <<'EOF' > batch_commit_test.go
package main

import (
	"fmt"
	"os"
	"path/filepath"

	"github.com/rosedblabs/rosedb/v2"
	"github.com/rosedblabs/rosedb/v2/utils"
)

func main() {
	// Create a temporary directory for the test database
	dir, err := os.MkdirTemp("", "rosedb-batch-test")
	if err != nil {
		panic(err)
	}
	defer os.RemoveAll(dir)

	// Set up database options
	options := rosedb.DefaultOptions
	options.DirPath = dir

	// Open database
	db, err := rosedb.Open(options)
	if err != nil {
		panic(err)
	}
	defer db.Close()

	// Test 1: Try to commit a batch twice
	fmt.Println("Test 1: Trying to commit a batch twice")
	batch1 := db.NewBatch(rosedb.DefaultBatchOptions)
	err = batch1.Put([]byte("key1"), []byte("value1"))
	if err != nil {
		panic(err)
	}

	// First commit should succeed
	err = batch1.Commit()
	if err != nil {
		panic(fmt.Sprintf("First commit failed: %v", err))
	}
	fmt.Println("First commit succeeded")

	// Second commit should fail with ErrBatchCommitted
	err = batch1.Commit()
	if err == rosedb.ErrBatchCommitted {
		fmt.Println("Second commit correctly failed with ErrBatchCommitted")
	} else {
		fmt.Printf("ERROR: Second commit should have failed with ErrBatchCommitted, but got: %v\n", err)
	}

	// Test 2: Try to use DB methods after batch commit (should be allowed)
	fmt.Println("\nTest 2: Using DB methods after batch commit")
	err = db.Put([]byte("key2"), []byte("value2"))
	if err != nil {
		fmt.Printf("ERROR: DB.Put after batch commit failed: %v\n", err)
	} else {
		fmt.Println("DB.Put after batch commit succeeded")
	}

	fmt.Println("Tests completed")
}
EOF
```

